import sys
from collections import defaultdict, deque

def topological_sort(packages, dependencies):
    in_degree = {pkg: 0 for pkg in packages}
    graph = defaultdict(list)

    for pkg, deps in dependencies.items():
        for dep in deps:
            graph[dep].append(pkg)
            in_degree[pkg] += 1

    queue = deque([pkg for pkg in in_degree if in_degree[pkg] == 0])
    result = []

    while queue:
        # Get the smallest package name with zero in-degree
        current = min(queue)
        queue.remove(current)
        result.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) == len(packages):
        return result
    else:
        return None

def main():
    input = sys.stdin.read().strip().split('\n')
    index = 0

    while True:
        n = int(input[index])
        if n == 0:
            break
        index += 1

        packages = set()
        dependencies = {}

        for _ in range(n):
            line = input[index].split()
            pkg = line[0]
            deps = line[1:]
            packages.add(pkg)
            dependencies[pkg] = deps
            index += 1

        order = topological_sort(packages, dependencies)

        if order:
            for pkg in order:
                print(pkg)
        else:
            print("cannot be ordered")

        if index < len(input):
            print()

main()
